pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        vm.assume(target != address(0) && value <= address(this).balance);
        // Deploy a helper that can receive ETH and execute arbitrary logic
        Helper helper = new Helper();
        // Fund the contract owner with enough ETH
        address owner = c.owner();
        vm.deal(owner, value);
        vm.prank(owner);
        // Record target balance before
        uint256 balanceBefore = address(helper).balance;
        // Call sendMoney with the helper as target and the provided data
        c.sendMoney{value: value}(address(helper), value, data);
        uint256 balanceAfter = address(helper).balance;
        // In reference: target receives value and executes data.
        // In buggy: target only receives value, data is ignored.
        // If data is empty, both behave identically (balanceAfter == balanceBefore + value).
        // If data is non-empty and makes target return/send ETH elsewhere (e.g., selfdestruct),
        // balanceAfter will be lower than balanceBefore + value in reference.
        // The buggy version always results in balanceAfter == balanceBefore + value.
        // The invariant we assert: If data is empty, balanceAfter MUST equal balanceBefore + value.
        // But for ALL inputs, the reference ensures this is true only when data is empty,
        // while the buggy version satisfies it for ALL inputs.
        // Therefore, asserting that (data.length == 0) implies (balanceAfter == balanceBefore + value)
        // holds on reference but the buggy version breaks the reverse (if data non-empty, reference may not satisfy,
        // but buggy always does). To differentiate, we assert a property that the buggy ALWAYS satisfies,
        // but reference does NOT: balanceAfter == balanceBefore + value.
        // The reference fails this when data causes ETH to be sent away.
        assertTrue(balanceAfter == balanceBefore + value);
    }
}

contract Helper {
    fallback() external payable { }
}

