pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, bytes memory data) public {
        vm.assume(value > 0);
        vm.assume(value <= address(c).balance);
        // The data must be a call to withdrawAll on this contract, ensuring the target is the contract itself
        bytes memory payload = abi.encodeWithSelector(C.withdrawAll.selector);
        vm.assume(keccak256(data) == keccak256(payload));

        uint256 balanceBefore = address(c).balance;
        c.sendMoney(address(c), value, data);
        uint256 balanceAfter = address(c).balance;

        // Reference: data executed -> withdrawAll called, balance reduced by value
        // Buggy: data ignored -> just transfer, balance unchanged
        assertTrue(balanceAfter == balanceBefore - value);
    }
}

