pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes calldata data) public {
        // Ensure we don't send money to ourselves to avoid complex reentrancy loops that
        // break the reference, keep value within balance after funding
        vm.assume(target != address(c));
        // Bound value to reasonable range to avoid overflow and keep gas manageable
        value = bound(value, 0, 1 ether);

        // Fund the contract with enough ETH to send
        vm.deal(address(c), value + 1 ether);

        // Record initial balances before the call
        uint256 initialContractBalance = address(c).balance;
        uint256 initialTargetBalance = target.balance;

        // The owner performs the call
        bool refOk;
        vm.prank(c.owner());
        try c.sendMoney(target, value, data) {
            refOk = true;
        } catch {
            refOk = false;
        }

        // After the call, compute final balances
        uint256 finalContractBalance = address(c).balance;
        uint256 finalTargetBalance = target.balance;

        // General rule: If data is non-empty, the reference does not guarantee success;
        // the buggy transfer always succeeds (never reverts) for the same ETH transfer.
        // Hence if data.length > 0, it must NOT be the case that the reference always
        // succeeds and the target's balance increase is exactly value without side-effects.
        // The bug breaks: for non-empty data, the mutant always succeeds and increases
        // target balance by value, ignoring data execution, while reference may revert
        // or have different balance effects due to data execution.
        // Concretely: when data is non-empty, the reference success status is not
        // unconditionally true; the mutant makes it always true. So the invariant
        // "if data is non-empty, then the reference call does not succeed AND increase
        // target balance exactly by value" holds for the reference (because it might revert
        // or execute data changing balances), but the mutant violates it by making
        // the call succeed and increase balance by value for the same inputs.
        // We encode: if data.length > 0, then it is NOT the case that refOk &&
        // (finalTargetBalance - initialTargetBalance) == value &&
        // (initialContractBalance - finalContractBalance) == value.
        // True for reference, false for mutant.
        if (data.length > 0) {
            bool mutantPattern = refOk && 
                (finalTargetBalance - initialTargetBalance == value) &&
                (initialContractBalance - finalContractBalance == value);
            assertTrue(!mutantPattern);
        } else {
            // Empty data: both behave identically (transfer succeeds), skip assertion or assert true
            assertTrue(true);
        }
    }
}

